def parse_log_entry(line):
    parts = line.split()
    m = int(parts[0])
    problem = parts[1]
    result = parts[2]

    # Dictionary to count the number of problems each player has solved
    problem_count = {}
    if problem in problem_count:
        problem_count[problem] += 1
    else:
        problem_count[problem] = 1

    return {
        'm': m,
        'problem': problem,
        'result': result,
        'problems': list(problem_count.values())
    }

def calculate_time_score(log_entries):
    total_problems_solved = 0
    total_time_score = 0
    for entry in log_entries:
        problems = parse_log_entry(entry)

        # Check if the problem was solved or not
        if problems['result'] == 'right':
            total_problems_solved += 1
        else:
            penalties = sum(problems['problems'])
            total_time_score += penalties

    return total_problems_solved, total_time_score

def main():
    while True:
        log_entry = input().strip()
        if log_entry == '-1':
            break

        result = calculate_time_score([parse_log_entry(line) for line in log_entry.split()])

        # Print the results
        print(f"Total problems solved: {result[0]}")
        print(f"Total time score: {result[1]}")

if __name__ == "__main__":
    main()

