def count_cannibalistic_loops(matrix):
    """
    Counts the number of closed loops in a rectangular array of black and white pixels.

    :param matrix: A list of lists where each sublist represents an image.
    :return: The number of loops in the input.

    Explanation:
    - We iterate over each element of the matrix, which represents an image.
    - For each element, we check its neighbors. If a neighbor is also black and not already counted, we increment our loop count.
    - We return the total count of loops found.
    """
    m = len(matrix)
    n = len(matrix[0])
    loops_count = 0

    for i in range(m):
        for j in range(n):
            if matrix[i][j] == '#':
                # Check top neighbor
                if (i > 0 and matrix[i-1][j] == '#') or (matrix[i][j+1] == '#'):
                    loops_count += 1

                # Check bottom neighbor
                if (i < m-1 and matrix[i+1][j] == '#') or (matrix[i][j-1] == '#'):
                    loops_count += 1

                # Check left neighbor
                if (j > 0 and matrix[i][j-1] == '#') or (matrix[i][j+1] == '#'):
                    loops_count += 1

                # Check right neighbor
                if (j < n-1 and matrix[i][j+1] == '#') or (matrix[i][j-1] == '#'):
                    loops_count += 1

    return loops_count

