def count_closed_loops(m, n):
    # Initialize a 2D list to store the grid of pixels
    grid = [[0] * n for _ in range(m)]

    # Parse the input and populate the grid
    for i in range(m):
        line = input()
        for j in range(n):
            if line[j] == '#':
                grid[i][j] = 1

    # Initialize a counter for closed loops
    closed_loop_count = 0

    # Iterate over each pixel in the grid
    for i in range(m):
        for j in range(n):
            if grid[i][j]:
                # Check all adjacent pixels
                if j + 1 < n and grid[i][j + 1] == 1:
                    closed_loop_count += 1
                if j - 1 >= 0 and grid[i][j - 1] == 1:
                    closed_loop_count += 1
                if i + 1 < m and grid[i + 1][j] == 1:
                    closed_loop_count += 1
                if i - 1 >= 0 and grid[i - 1][j] == 1:
                    closed_loop_count += 1

    return closed_loop_count

