def count_loops(m, n):
    loop_count = {}

    for i in range(m):
        for j in range(n):
            current = input()

            # Check if the cell is not empty and has exactly two '#'
            if current != '' and len(current) == 2 and current[0] == '#' and current[-1] == '#':
                adjacent_cells = []

                # Check all four adjacent cells
                for dx, dy in [(-1, -1), (-1, 0), (0, -1), (0, 1)]:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < m and 0 <= ny < n:
                        adjacent_cells.append((nx, ny))

                # Increment the count for each loop found
                for nx, ny in adjacent_cells:
                    if (nx, ny) not in loop_count:
                        loop_count[(nx, ny)] = 1
                    else:
                        loop_count[(nx, ny)] += 1

    # The number of loops is the total count of all entries in the dictionary
    return len(loop_count)

