def convert_apaxian_name(name):
    # Convert name to lowercase and filter out non-letter characters
    filtered = ''.join(char.lower() for char in name if char.isalpha())

    # Count consecutive occurrences of the same letter
    count = 1
    prev_char = None

    # Process each character in the filtered string
    for char in filtered:
        if prev_char is not None and prev_char == char:
            count += 1
        else:
            if count > 2:
                name = name.replace(char, str(count))
            prev_char = char
            count = 1

    # Handle last sequence of the same letter
    if count > 2:
        name = name.replace(prev_char, str(count))

    return name

