def generate_extended_name(Y, P):
    # Convert strings to lowercase and trim them to remove any leading or trailing spaces
    Y = Y.strip().lower()
    P = P.strip().lower()

    if not Y:
        raise ValueError("Input Y is empty")

    if not P:
        raise ValueError("Input P is empty")

    # Check the last character of Y
    if Y[-1] == 'e':
        # Add 'x' to Y and extend with P
        return Y + 'ex' + P

    # Iterate over vowels to handle other cases
    for vowel in set('aeiou'):
        if Y[-1] == vowel:
            # Remove the last vowel from Y
            Y = Y[:-1]
            # Extend by P
            return Y + P

