def circle_to_square(x, y, r):
    """
    Calculate the smallest possible square with side length r that can fit a circle centered at (x, y)

    Parameters:
    x (int): The x-coordinate of the center of the circle.
    y (int): The y-coordinate of the center of the circle.
    r (int): The radius of the circle.

    Returns:
    tuple: A tuple containing the x and y-coordinates of one corner of the square.
    """
    # Calculate the square side length
    side_length = 2 * r

    # Ensure the coordinates are within the valid range
    if x < -10**9 or x > 10**9:
        raise ValueError("x-coordinate out of bounds")
    if y < -10**9 or y > 10**9:
        raise ValueError("y-coordinate out of bounds")

    # Calculate the coordinates of the corner
    if side_length == 2 * r:
        return (x, y)
    else:
        square_x = x + (side_length // 2)
        square_y = y + (side_length // 2)

        # Ensure the coordinates are within the valid range for a square with side length r
        if square_x < -10**9 or square_x > 10**9:
            raise ValueError("square x-coordinate out of bounds")
        if square_y < -10**9 or square_y > 10**9:
            raise ValueError("square y-coordinate out of bounds")

        return (square_x, square_y)

def main():
    try:
        # Read input
        x, y = map(int, input().split())
        r = int(input())

        # Get the corner coordinates
        corner_coords = circle_to_square(x, y, r)

        print(f"Corner coordinates: ({corner_coords[0]}, {corner_coords[1]})")

    except ValueError as e:
        print(e)

