def kmp_function(s):
    n = len(s)
    pi = [0] * (n + 1)

    for i in range(1, n + 1):
        j = pi[i - 1]

        while j > 0 and s[j] != s[i]:
            j = pi[j - 1]

        if s[i] == s[j]:
            pi[i] = j + 1

    print("Short variation:", pi)

def mprat_function(s):
    n = len(s)
    m = len(set(s))  # Use set to remove duplicates
    p = [0] * (m + 1)

    for i in range(1, m + 1):
        j = p[i - 1]

        while j > 0 and s[j] != s[i]:
            j = p[j - 1]

        if s[i] == s[j]:
            p[i] = j + 1

    print("Long variation:", p)

