        # Update dominant suit count
        if suit == B:
            dominant_suit_count[num] += 1
        else:
            non_dominant_suit_count[num] += 1

        # Calculate points for each suit
        if num % 2 == 0:
            points += 3 * dominant_suit_count[num]
        else:
