def min_bombs_to_defeat(n):
    if n < 4:
        return -1  # impossible to defeat the boss in this case

    # Initialize a list to keep track of visited pillars and their bombs collected
    visited = set()
    bomb_collected = 0

    # Function to perform BFS from a given pillar
    def bfs(pillar):
        queue = [pillar]
        while queue:
            current_pillar = queue.pop(0)

            if current_pillar not in visited:
                visited.add(current_pillar)

                # Check if the boss is still hiding behind the current pillar
                for neighbor in ['left', 'right']:
                    next_pillar = current_pillar + neighbor
                    if 0 <= next_pillar < n and next_pillar not in visited:
                        queue.append(next_pillar)
                        bomb_collected += 1

    # Start BFS from each pillar to collect bombs
    for i in range(n):
        bfs(i)

    return bomb_collected

