def min_bombs_needed(n):
    if n <= 0:
        return None

    # Initialize variables
    bombs = 0
    current_pillar = 0

    # Iterate through each pillar
    while current_pillar < n - 1:
        # Check if the next pillar is adjacent to the current pillar or moves to an adjacent pillar
        if (current_pillar + 1) % n == current_pillar or (current_pillar - 1) % n == current_pillar:
            bombs += 1
        current_pillar = (current_pillar + 1) % n

    return bombs

