def is_valid(s):
    # Helper function to check if a substring is balanced
    def is_balanced(subseq):
        balance = 0
        for char in subseq:
            if char == '(' or char == '[':
                balance += 1
            elif char == ')' or char == ']':
                balance -= 1
            # If balance goes negative, it means there are more closing brackets than opening ones
            if balance < 0:
                return False
        return balance == 0

    # Check each substring starting from the first character to the last
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            # Recursively check substrings
            if is_balanced(s[i:j]):
                continue
            else:
                return False

    return True

