def isValidSequence(n, s):
    # Edge cases
    if n == 0:
        return "Valid"
    elif n < 2 or n > 100000:
        return "Invalid"

    # Memoization dictionary
    memo = {}

    def is_valid_left(i, j):
        # If we've already computed this state, return the result from the memo dictionary
        if (i, j) in memo:
            return memo[(i, j)]

        # Check if either part of the sequence is empty or contains only one character
        if i == n - 1 and j < n - 1 and s[i] not in "()[]{}":
            return "Invalid"

        # Split the input string into two parts
        left = s[:i]
        right = s[i:]

        # Recursively check if both parts are valid
        for l in range(len(left)):
            for r in range(l, len(right) + 1):
                # Check if both parts are valid
                if is_valid_left(i + 1, j + 1):
                    memo[(i, j)] = True
                    return True

        return False

    # Start the recursion with an empty string and index 0
    return is_valid_left(0, 0)

