        return "Invalid"
    if len(s) > n:
        return "Invalid"

    # Initialize a stack to keep track of opening brackets
    stack = []

    # Iterate over each character in the string
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return "Invalid"  # No matching opening bracket
            stack.pop()  # Match found, pop from stack

    # If stack is empty, all brackets are matched
    if not stack:
        return "Valid"
    else:
        return "Invalid"

