        return "Alice"

    # Initialize variables to store the maximum score for each player
    max_score_alice = -float('inf')
    max_score_bob = -float('inf')

    # Helper function to perform a recursive move
    def is_winning(branch_length):
        nonlocal max_score_alice, max_score_bob

        if branch_length == 1:
            return (branch_length > max_score_alice) or (branch_length > max_score_bob)

        for i in range(1, branch_length // 2 + 1):
            if can_win(branch_length - i):
                # If Bob can force Alice into a losing position
                if is_winning(branch_length - i):
                    # Update the maximum score for Alice
                    max_score_alice = max(max_score_alice, branch_length - i)

        return (max_score_alice > max_score_bob)

    # Start with all possible starting points
    for start in range(1, n // 2 + 1):
        if is_winning(start):
            return can_win(start)

    return "Bob"

