def shuffle_and_determine_initial_order(n):
    # Check if n is 1 or greater than 13
    if n < 2:
        return "No such sequence exists."

    # The trick only works for n = 1 and n > 13
    if n == 1:
        return "One card left: Ace of Spades"
    elif n == 14:
        return "Four cards left: 2 of Spades, 1 of Hearts, 4 of Diamonds, 2 of Clubs"

    # Find the correct order of n cards
    initial_order = list(range(1, n + 1))
    for _ in range(n - 1):
        card_to_move = initial_order.pop()
        index_to_move = initial_order.index(card_to_move)

        # Move the next card to its original position
        if index_to_move > 0:
            initial_order.insert(index_to_move - 1, initial_order[index_to_move])

    return ' '.join(map(str, initial_order))

