def is_valid_move(row1, col1, row2, col2):
    return 0 <= row1 < R and 0 <= col1 < C and (row2 == 0 or row2 - row1 == 1) and (col2 == 0 or col2 - col1 == 1)

def find_winner(R, C):
    # Algorithm: BFS to find the winner
    from collections import deque

    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    for _ in range(R * C):
        current_position = (0, 0)
        queue = deque([(current_position, None)])

        while queue:
            position, previous_move = queue.popleft()

            if previous_move == 'A':
                continue

            # Check all possible moves
            for move in directions:
                new_row, new_col = position[0] + move[0], position[1] + move[1]

                # If the new piece is empty and within bounds
                if 0 <= new_row < R and 0 <= new_col < C and (new_row == 0 or new_row - new_col == 1) and (new_col == 0 or new_col - new_row == 1):
                    queue.append((new_position, move))

    # Check the last remaining piece
    if len(queue) > 0:
        current_position = queue[0]
        return 'A' if is_valid_move(current_position[0], current_position[1], R-1, C-1) else 'B'

    return None

