def find_longest_loop(S, L):
    max_length = 0
    for i in range(1 << S):  # Use bitwise operations to count the number of ways to alternate colors
        current_length = 0
        for j in range(S):
            if (i >> j) & 1 == 1:  # Determine color based on the current segment length
                current_length += L[j]
            else:
                current_length -= L[j]
        max_length = max(max_length, current_length)
    return max_length

