def generate_antidote_sequence(n, antidote):
    return [antidote ** i for i in range(n)]

def backtrack(antidotes, current_index, path, n, target, visited):
    if len(path) == target:
        # We have found a valid ordering of subsets
        result.append(tuple(path))
        return

    for i in range(current_index, n):
        if antidote[i] ** (target - len(path)) in visited:
            continue
        visited.add(antidote[i])
        backtrack(antidotes, i + 1, path + [antidote[i]], n, target, visited)
        visited.remove(antidote[i])

def count_antidote_orders(n):
    if n < 1:
        return 0

    # Generate all possible antidotes
    antidotes = generate_antidote_sequence(n, 2 ** n - 1)

    # Initialize the result list
    result = []

    # Start backtracking with path length of 1
    backtrack(antidotes, 0, [], n, 1, set())

    return len(result)

