def transform_cipher(cipher_text):
    """
    Transform the input cipher text into a string containing only Per's name.

    :param cipher_text: The input cipher text on the whiteboard.
    :return: A string containing only Per’s name.
    """
    # Convert the cipher text to lowercase
    lower_cipher_text = cipher_text.lower()
    # Create an empty list to store the transformed characters
    result = []

    # Iterate over each character in the cipher text
    for char in lower_cipher_text:
        # Check if the character is a letter
        if char.isalpha():
            # Determine which letter to replace based on its ASCII value
            if char >= 'a' and char <= 'z':
                # For lowercase letters, calculate the replacement
                if (char - ord('a') + 1) % 3 == 0:
                    result.append(chr(ord('g') + (ord(char) - ord('a') + 1) % 3))
                else:
                    result.append(chr(ord('m') + (ord(char) - ord('a') + 1) % 3))
            elif char >= 'A' and char <= 'Z':
                # For uppercase letters, calculate the replacement
                if (char - ord('A') + 1) % 3 == 0:
                    result.append(chr(ord('G') + (ord(char) - ord('A') + 1) % 3))
                else:
                    result.append(chr(ord('M') + (ord(char) - ord('A') + 1) % 3))
        else:
            # If it's not a letter, just add the character to the result
            result.append(char)

    # Join the list into a string and return
    return ''.join(result)

