def calculate_area(polygon):
    if len(polygon) < 3:
        return 0.0
    n = len(polygon)
    area = 0.0
    for i in range(n):
        j = (i + 1) % n
        x1, y1 = polygon[i]
        x2, y2 = polygon[j]
        area += x1 * y2 - x2 * y1
    return abs(area) / 2.0

