def calculate_polygon_area(vertices):
    area = 0
    n = len(vertices)
    for i in range(n):
        # Calculate the contribution of the current vertex to the total area
        area += (vertices[i][1] * vertices[(i+1) % n][1]) - (vertices[i][0] * vertices[(i+1) % n][0])
    return abs(area / 2)

