def get_winner(colleagues):
    # Initialize variables to track the best score and categories with the best score
    best_score = float('-inf')
    best_categories = []

    # Iterate over each response for each colleague
    for i, response in enumerate(colleagues):
        # Count the number of times each costume was used by a colleague
        costume_counts = {}
        for costume in response.split():
            if costume in costume_counts:
                costume_counts[costume] += 1
            else:
                costume_counts[costume] = 1

        # Calculate the score based on the number of each costume
        score = sum(costume_counts.values())

        # Check if this is the best score or a tie
        if score > best_score:
            best_score = score
            best_categories = [response]
        elif score == best_score:
            best_categories.append(response)

    # Print the result in lexicographic order
    return ' '.join(sorted(best_categories))

