def check_cpr(cpr_number):
    """Check if the given CPR number is valid according to the modulo 11 rule."""
    digits = list(map(int, cpr_number.split('-')))

    # Check for empty input or minimum/maximum values
    if len(digits) < 6 or len(digits) > 10:
        return "0"

    # Calculate the check digit using a simple formula
    if digits[9] != 0:
        raise ValueError("The CPR number does not have a check digit.")

    sum_of_products = sum([4 * d + 3 * c + 2 * d + 7 * c + 6 * c + 5 * c + 4 * c + 3 * c + 2 * c + 1 for d in digits])

    # Calculate the check digit using the modulo operation
    check_digit = (sum_of_products % 11)

    return str(check_digit)

def main():
    """Main function to validate a CPR number."""
    try:
        cpr_number = input("Enter a 10-digit CPR number: ")
        result = check_cpr(cpr_number)
        print(result)
