def day_of_week(D, M):
    # Check if inputs are valid
    if D < 1 or D > 31:
        return "Invalid input: Day must be between 1 and 31"

    if M < 1 or M > 12:
        return "Invalid input: Month must be between 1 and 12"

    # Determine the number of days in each month
    if M == 2:
        if (D % 4) != 0:
            return "Invalid input: February is not a leap year"
        else:
            if D >= 29:
                return "Invalid input: February has 29 days, except for the year divisible by 4"
    elif M == 4 or M == 6 or M == 9 or M == 11:
        return "Invalid input: April, June, September, and November have 30 days"
    else:
        return "Invalid input: Month must be between 2 and 12"

    # Determine the first day of the week for each month
    if M == 2:
        # February has 29 days, except for the year divisible by 4
        if (D % 4) != 0:
            return "Friday"
        else:
            return "Monday"  # Leap year is considered a leap year, so we don't count 30 days
    elif M == 4 or M == 6 or M == 9 or M == 11:
        if (D % 2) != 0:
            return "Tuesday"
        else:
            return "Monday"  # Leap year is considered a leap year, so we don't count 30 days
    elif M == 8:
        return "Wednesday"
    else:
        return "Thursday"

