def reconstruct_array(N):
    # Initialize the matrix with zeros
    matrix = [[0] * N for _ in range(N)]

    # Create a list of indices that are not on the main diagonal
    non_diagonal_indices = [i for i in range(N) if i != N - 1]

    # Populate the main diagonal with 0s
    for idx in non_diagonal_indices:
        matrix[idx][idx] = 0

    # Calculate bitwise AND between elements above each element
    for i in range(1, N):
        for j in range(N):
            if i != N - 1 and matrix[i][j] == matrix[i - 1][j]:
                matrix[i][j] = 0

    return matrix

