def encrypt_message(encrypted_message, key):
    # Check if the length of key matches the length of encrypted message
    if len(key) != len(encrypted_message):
        raise ValueError("Key must be the same length as encrypted message")

    # Ensure the key contains only alphabetic characters
    for char in key:
        if not char.isalpha():
            raise ValueError("Key must contain only alphabetic characters")

    # Dictionary to store character pairs and their decrypted counterparts
    decryption_dict = {}

    # Encrypt each character in encrypted_message
    for index, char in enumerate(encrypted_message):
        if char.isupper():
            base_char = ord('A')
        else:
            base_char = ord('a')

        # Calculate the shift based on whether index is even or odd
        shift = (ord(char) - base_char + int(key[index % len(key)])) % 26

        # Find the corresponding decrypted character
        if char.isupper():
            decrypted_char = chr(ord('A') + (shift - base_char))
        else:
            decrypted_char = chr(ord('a') + (shift - base_char))

        # Store the pair and its decrypted counterpart in the dictionary
        decryption_dict[(ord(char) - base_char, index % len(key))] = decrypted_char

    # Convert decrypted characters to a single string
    return ''.join(decryption_dict.values())

