def encrypt_message(message, key):
    """
    Encrypts the given message using a Vigenère cipher.

    :param message: The encrypted message to be decrypted.
    :param key: The key used for encryption.
    :return: The decrypted message.
    """
    # Ensure both message and key are of equal length
    if len(message) != len(key):
        raise ValueError("Message and key must be of equal length.")

    # Function to shift a single character in the alphabet
    def shift_char(char, shift_value):
        if 'A' <= char <= 'Z':
            return chr((ord(char) - ord('A') + shift_value) % 26)
        elif 'a' <= char <= 'z':
            return chr((ord(char) - ord('a') + shift_value) % 26)
        return char

    # Encrypt each character in the message
    encrypted_message = ''.join(shift_char(c, key[i % len(key)]) for i, c in enumerate(message))

    return encrypted_message

def decrypt_message(encrypted_message, key):
    """
    Decrypts the given encrypted message using a Vigenère cipher.

    :param encrypted_message: The encrypted message to be decrypted.
    :param key: The key used for decryption.
    :return: The decrypted message.
    """
    # Ensure both message and key are of equal length
    if len(encrypted_message) != len(key):
        raise ValueError("Message and key must be of equal length.")

    # Function to shift a single character in the alphabet backwards
    def shift_char(char, shift_value):
        if 'A' <= char <= 'Z':
            return chr((ord(char) - ord('A') - shift_value) % 26)
        elif 'a' <= char <= 'z':
            return chr((ord(char) - ord('a') - shift_value) % 26)
        return char

    # Decrypt each character in the encrypted message
    decrypted_message = ''.join(shift_char(c, key[(len(key) - i - 1) % len(key)]) for i, c in enumerate(encrypted_message))

    return decrypted_message

