def decode_message(encoded):
    # Split the encoded message into a list of characters
    chars = list(encoded)

    # Get the length of the message
    n = len(chars)

    # Create a 2D list to simulate the square matrix
    grid = [[0] * n for _ in range(n)]

    # Place characters in the matrix
    for i in range(n):
        for j in range(n):
            if i == 0:
                grid[j][i] = chars[i]
            else:
                if i % 2 == 0:
                    grid[(n - 1) - i // 2][(j + 1) // 2] = chars[i]
                else:
                    grid[(n - 1) - i // 2][(j - 1) // 2] = chars[i]

    # The matrix now contains the original message
    return ''.join(grid)

