def is_balanced(s):
    # Initialize counters for balance
    balance = 0

    # Iterate over each character in the string
    for char in s:
        # If the character is an opening parenthesis, increment the counter
        if char == '(':
            balance += 1
        # If the character is a closing parenthesis, decrement the counter
        elif char == ')':
            balance -= 1

        # If at any point balance goes negative, it means there are more closing than opening parentheses
        if balance < 0:
            return False

    # If balance is zero, all parentheses are matched correctly
    return balance == 0

