import math

def paper_flights(h, k, v, s):
    # Handle edge cases
    if h <= 0:
        return 0
    elif k <= 0:
        return 0
    elif v >= k:
        return h - 1
    elif 0 < v < k:
        return v
    elif h == 0:
        return 0

    # Initialize variables
    max_v = math.floor(v / 10)
    max_h = int(h / max_v)

    # Process the sequence of movements
    for _ in range(4):
        if v >= k:
            h += 1
        elif 0 < v < k:
            h -= 1
        else:
            if s > 0:
                h -= 1

    return int(h)

def predict_flight_distance(h, k, v, s):
    # Check if all inputs are within the valid range
    if not (1 <= h <= 10**3) or not (1 <= k <= 10**3) or not (1 <= v <= 10**3) or not (1 <= s <= 10**3):
        raise ValueError("All inputs must be between 1 and 10^3.")

    # Determine the initial velocity
    if s > 0:
        v += s

    distance = 0
    current_velocity = v

    while current_velocity >= k:
        distance += 1
        current_velocity -= max(1, current_velocity // 10)

    return int(distance)

