def encrypt_message(message: str) -> str:
    # Step 1: Convert message to Morse code without pauses but with a string of numbers to indicate code lengths.
    morse_code = ""
    for char in message:
        if char == "A":
            morse_code += ".-"
        elif char == "B":
            morse_code += "-..."
        elif char == "C":
            morse_code += "-.-."
        elif char == "D":
            morse_code += "--"
        elif char == "E":
            morse_code += "."
        elif char == "F":
            morse_code += "..-."
        elif char == "G":
            morse_code += "--. "
        elif char == "H":
            morse_code += .....
        elif char == "I":
            morse_code += ..   #
        elif char == "J":
            morse_code += .---  #
        elif char == "K":
            morse_code += -.-  #
        elif char == "L":
            morse_code += .-..  #
        elif char == "M":
            morse_code += "--. "
        elif char == "N":
            morse_code += -.   #
        elif char == "O":
            morse_code += "---."
        elif char == "P":
            morse_code += ".--."
        elif char == "Q":
            morse_code += "--.-  "
        elif char == "R":
            morse_code += .-.  #
        elif char == "S":
            morse_code += "...   "
        elif char == "T":
            morse_code += "-"
        elif char == "U":
            morse_code += "..-  "
        elif char == "V":
            morse_code += .....
        elif char == "W":
            morse_code += .--     #
        elif char == "X":
            morse_code += -..-. #
        elif char == "Y":
            morse_code += ...   #
        elif char == "Z":
            morse_code += --.  #
    # Step 2: Reverse the string of numbers.
    code_lengths = list(morse_code)
    code_lengths.reverse()

    # Step 3: Convert dots and dashes back into the text using the reversed string of numbers as code lengths.
    decoded_message = ""
    for i in range(len(code_lengths)):
        num_dots = int(code_lengths[i])
        num_dashes = len(code_lengths) - i - 1
        decoded_message += (char for char in morse_code if num_dots != 0 and num_dashes != 0).next()

    return decoded_message

