def find_possible_wids(width, partitions):
    # Initialize an empty list to store possible widths
    possible_wids = []

    # Loop through each partition location
    for L in partitions:
        # Check if the current partition is within the bounds of the room and not at the left wall
        if 0 <= L < width - 1:
            # Calculate the width of the meeting space using the formula: W * (P + 1) / P
            wid = width * (L + 1) // P

            # Append the calculated width to the list of possible widths
            possible_wids.append(wid)

    # Return the sorted list of possible widths
    return sorted(possible_wids)

