def compute_window_width(data):
    """
    Given a set of data in format (m, n), compute the dimensions of the final window after placing all rectangles.

    Parameters:
    - data: A list of tuples, where each tuple contains two integers (width and height) for one rectangle.

    Returns:
    - The width of the resulting window.
    """
    m, n = 0, 0
    for _, w in data:
        if w > m:
            m = w
        elif w < n:
            n = w
    return min(m, n)

