def find_minimum_pilots(cities, pilots, graph):
    # Function to calculate minimum number of pilots needed
    def min_pilots(start, end):
        if start == end:
            return 1

        count = float('inf')

        for neighbor in graph[start]:
            if neighbor != end:
                count = min(count, 1 + min_pilots(neighbor, end))

        return count

    # Iterate through all pairs of cities to find the minimum number of pilots
    min_count = float('inf')
    for i in range(cities):
        for j in range(i + 1, cities):
            if graph[i][j] > 0:
                min_count = min(min_count, min_pilots(i, j))

    return min_count

