def find_trusted_pilots(n, m, flights):
    # Represent graph using adjacency list
    adj_list = {i: [] for i in range(n)}

    for a, b in flights:
        adj_list[a].append(b)
        adj_list[b].append(a)

    # BFS to find all possible routes between any two cities
    def bfs(start):
        queue = [(start, 1)]
        visited = set()
        while queue:
            current_city, trust_count = queue.pop(0)
            if current_city not in visited:
                visited.add(current_city)
                for neighbor in adj_list[current_city]:
                    if neighbor not in visited:
                        queue.append((neighbor, trust_count + 1))

    # Count the number of pilots that can be trusted to fly from one city to another
    trusted_count = 0
    for a, b in flights:
        if a != b and (a, b) in adj_list[a] or (b, a) in adj_list[b]:
            trusted_count += 1

    return trusted_count

