def is_connected(graph):
    # Check if a graph is connected by Depth-First Search (DFS)
    visited = [False] * n
    def dfs(g, node, depth=0):
        if visited[node]:
            return True
        visited[node] = True
        for neighbor in g[node]:
            if not dfs(g, neighbor, depth + 1):
                return False
        return True

    # Check each city with DFS starting from it
    for i in range(n):
        if not dfs(graph, i):
            return False
    return True

