def spread_water(N, M):
    # Create an empty grid for the final result
    grid = [["." for _ in range(M)] for _ in range(N)]

    def update_grid(state):
        for i in range(N):
            for j in range(M):
                if state[i][j] == "V":
                    water_count = 0
                    # Count adjacent water cells
                    for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nx, ny = i + dx, j + dy
                        if 0 <= nx < N and 0 <= ny < M:
                            if grid[nx][ny] == "A":
                                water_count += 1
                            elif grid[nx][ny] == "W":
                                grid[nx][ny] = "V"
                    # If there are any water cells adjacent, change the state to water
                    if water_count > 0:
                        grid[i][j] = "W"

    # Simulate the spread of water
    for _ in range(100):  # Example: Spread for 100 seconds
        update_grid(grid)

    return "\n".join(["".join(row) for row in grid])

