def compute_efficiency_gap(P, D, precincts):
    # Count the number of votes for each party
    a_count = [0] * P
    b_count = [0] * P

    for i in range(P):
        a_i, b_i = precincts[i]

        if a_i != b_i:
            a_count[a_i] += 1
            b_count[b_i] += 1

    # Determine the party that wins and the wasted votes for each party
    total_wasted_A = 0
    total_wasted_B = 0

    for i in range(P):
        if a_count[i] > b_count[i]:
            total_wasted_A += precincts[i][2]
        elif a_count[i] < b_count[i]:
            total_wasted_B += precincts[i][2]

    # Compute the efficiency gap
    efficiency_gap = abs(total_wasted_A - total_wasted_B) / D

    return efficiency_gap, a_count, b_count

