import sys
from collections import deque

def distance(x1, y1, x2, y2):
    # Calculate Euclidean distance
    return ((x2 - x1)**2 + (y2 - y1)**2)**0.5

def find_min_distance():
    # Read input
    x1, y1, x2, y2 = map(int, sys.stdin.readline().split())

    # Check if the points are within the axis-aligned rectangle
    if x1 < 0 or x2 < 0 or y1 < 0 or y2 < 0:
        raise ValueError("Input points must be strictly outside the rectangle.")

    # Initialize queue with the start point (x1, y1)
    queue = deque([(x1, y1)])
    visited = set()

    # Perform BFS
    while queue:
        x, y = queue.popleft()

        # Check if the current position is within the house
        if x == x2 and y == y2:
            return distance(x, y, x2, y2)

        # Explore four possible directions: right, down, left, up
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < 999 and 0 <= ny < 999 and (nx, ny) not in visited:
                queue.append((nx, ny))
                visited.add((nx, ny))

    return float('inf')  # Return infinity if no path is found

