def find_gis(n):
    # Input validation
    if n <= 0:
        return []
    elif len(set(n)) != n:
        return "Input contains duplicate numbers."

    current_state = [n[0]]
    l = 1

    for i in range(1, n):
        if current_state[-1] < n[i]:
            current_state.append(n[i])
            l += 1
        elif current_state[-1] > n[i]:
            # Check for duplicates and move to the next state
            while len(set(current_state)) > len(current_state) - 1:
                current_state.pop()
            current_state.append(n[i])
            l += 1

    return l, current_state

