def count_groups(fire_safety_limit, event_count):
    # Initialize variables to keep track of groups and people on the terrace
    groups = 0
    current_people = 0

    # Read input events
    for _ in range(event_count):
        event_type = input().strip()

        if event_type == 'enter':
            # Process group entering, increment count if current_people exceed fire_safety_limit
            if current_people + 1 <= fire_safety_limit:
                groups += 1
                current_people += 1
            else:
                print(f"Group {event_type} prevented entry due to maximum {fire_safety_limit}.")

        elif event_type == 'leave':
            # Process group leaving, decrement count if current_people exceed 0
            if current_people > 0:
                current_people -= 1
                groups += 1
            else:
                print(f"Group {event_type} was denied for leaving. Cannot remove any more people.")

    return groups

