                # Determine power level and energy for each card
                power1, energy1 = card_list1[0], sum(card_list1[1:])
                power2, energy2 = card_list2[0], sum(card_list2[1:])

                # Check if player 1 can win the current turn
                if power1 >= energy1 and locations["power"] - (total_power + energy1) < power2:
