def find_min_jumps(start_x, start_y, end_x, end_y):
    # Directions to move the knight (up, down, left, right)
    dx = [-2, 2, 0, 0]
    dy = [0, 0, -2, 2]

    min_jumps = float('inf')
    hiding_places = []

    def dfs(x, y):
        nonlocal min_jumps, hiding_places
        if (x == end_x) and (y == end_y):
            if min_jumps > jumps:
                min_jumps = jumps
                hiding_places = [str((x, y))]
            return

        for dx, dy in zip(dx, dy):
            nx, ny = x + dx, y + dy
            if is_valid_move(nx, ny):
                dfs(nx, ny)

    # Start DFS from the starting position (a1)
    dfs(start_x, start_y)
    return min_jumps, hiding_places

