def min_moves(H, T):
    if H == 0 or T == 0:
        return -1

    # Case 1: Only one head remains (i.e., H = 1)
    if H == 1:
        return abs(T - 1)

    # Case 2: No more cuts can be made
    if T <= 0:
        return float('inf')

    # Recursive case for all other states
    left_moves = min_moves(H, T - 1) + 1  # Move to cut off one tail
    right_moves = min_moves(H, T) + 1  # Move to cut off two tails

    # Return the minimum of the two possible moves
    return min(left_moves, right_moves)

