def calculate_moves(H, T):
    # Initialize variables
    result = 0
    dead = False

    # Process each move
    while H > 0 or T > 0:
        if dead:
            break

        # Cut off all heads and tails
        if H > 0:
            result += 1
            H -= 1
        if T > 0:
            result += 2
            T -= 2

    # Check for deadly case
    if H == 0 and T == 0:
        result = -1

    return result

