            graph[i + 1].append(edges[1])
        elif edges[1] == 1:
            graph[i + 1].append(edges[0])

    def topological_sort(node):
        while graph[node]:
            # Find the next unvisited node
            neighbor = graph[node].pop(0)
            topological_sort(neighbor)

        # Mark the current node as visited
        graph[node] = []
        return

    # Perform topological sorting
    topo_order = []
    for node in range(1, n + 1):
