    # Count triangles using Floyd-Warshall algorithm
    # This is a well-known algorithm that computes all shortest paths in an undirected graph.
    def floyd_warshall(graph):
        num_vertices = len(graph.keys())

        # Initialize the distances matrix with infinity
        dist = [[float('inf')] * num_vertices for _ in range(num_vertices)]
        dist[0][0] = 0  # Distance to start city is 0

        # Relax each edge
        for k in range(1, num_vertices):
            for i in range(num_vertices):
                for j in range(num_vertices):
                    if graph[i][j]:
                        new_distance = dist[i][k] + graph[k][j]
                        if new_distance < dist[j][i]:
                            dist[j][i] = new_distance

        return dist

    # Find the distances matrix
    distances = floyd_warshall(graph)

    # Count the number of triangles
    num_triangles = 0
    for i in range(num_vertices):
        for j in range(i + 1, num_vertices):
            if distances[i][j] == 3:
                num_triangles += 1

    return num_triangles

