def convolve_image(image, kernel):
    """
    Applies a 2x2 kernel to an image and returns the resulting image.

    Parameters:
    - image: A list of lists representing the image, where each inner list contains integers.
    - kernel: A list of lists representing the convolution kernel, where each inner list represents a channel (height or width).

    Returns:
    - The resulting image after convolution.
    """
    # Get the height and width of the image
    H, W = len(image), len(image[0])
    N, M = len(kernel), len(kernel[0])

    # Initialize the result image with zeros
    result = [[0] * (W - N + 1) for _ in range(H - N + 1)]

    # Perform convolution
    for i in range(H):
        for j in range(W):
            for k in range(N):
                for l in range(M):
                    sum_value = 0
                    for m in range(N):
                        for n in range(M):
                            if i + m < H and j + n < W:
                                sum_value += image[i + m][j + n] * kernel[m][n]
                    result[i][j] = sum_value

    return result

