    x3, y3 = vertices[1]

    # Shoelace formula
    area = abs((x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2)

    return area

def count_trees(vertices):
    N = len(vertices)
    tree_set = set()

    for i in range(N):
        for j in range(i + 1, N):
            if vertices[i] != vertices[j]:
                tree_set.add((vertices[i], vertices[j]))

    return len(tree_set)

