def calculate_expenses(N, incomes):
    # Check if the input is valid
    if N <= 0 or len(incomes) != N:
        raise ValueError("Invalid input: N must be a positive integer and incomes must have the same length.")

    # Initialize the sum of expenses
    total_expenses = 0

    # Iterate over each expense and income pair
    for k_i, i in enumerate(incomes):
        # Calculate the adjusted income if necessary
        if k_i > 0:
            # Add the minimum value to the income if it's positive
            if i < 0:
                i = -i
            else:
                continue

        # Add the adjusted expense to the total expenses
        total_expenses += k_i * i

    return total_expenses

