def count_missing_cards(deck_labels):
    # Split the deck labels into a list of card labels
    cards = deck_labels.split()

    # Dictionary to count the number of each suit
    suit_count = {'P': 0, 'K': 0, 'H': 0, 'T': 0}

    # Count the number of cards in each suit
    for label in cards:
        if label.startswith('P'):
            suit_count['P'] += 1
        elif label.startswith('K'):
            suit_count['K'] += 1
        elif label.startswith('H'):
            suit_count['H'] += 1
        elif label.startswith('T'):
            suit_count['T'] += 1

    # Calculate the number of missing cards for each suit
    missing_cards = {'P': sum(suit_count['P']), 'K': sum(suit_count['K']), 'H': sum(suit_count['H']), 'T': sum(suit_count['T'])}

    # Print the result as a space-separated string
    return " ".join(map(str, missing_cards.values()))

