def calculate_missing_cards(s):
    # Dictionary to map suits to their corresponding numbers
    suit_to_number = {
        'P': 1, 'K': 2, 'H': 3, 'T': 4, 'J': 5, 'Q': 6, 'A': 7
    }

    # Split the input string into individual card labels
    cards = s.split()

    # Initialize a counter for missing cards in each suit
    missing_cards = {suit: 0 for suit in suit_to_number}

    # Count the number of cards with matching suits
    for card in cards:
        if card in suit_to_number:
            missing_cards[card] += 1

    return missing_cards

