    words = encoded.split()
    decoded_words = []

    for word in words:
        vowels = 'aeiou'

        # Process each character in the word
        decoded_word = ''
        for char in word:
            if char in vowels:
                # If it's a vowel, add 'p' and repeat the vowel again
                decoded_word += 'pp'
            else:
                # Otherwise, just append the original character
