def autokey_encrypt(ciphertext, secret):
    # Ensure the length of the secret is greater than the ciphertext
    if len(secret) > len(ciphertext):
        raise ValueError("The secret word must be longer than the ciphertext.")

    # Initialize variables
    message = ciphertext[len(secret):]
    key = secret[0:len(secret)]
    encrypted_message = []

    # Encrypt each letter of the message
    for char in message:
        if char.isalpha():
            if char == 'E':
                encrypted_char = 'G'
            elif char == 'S':
                encrypted_char = 'Q'
            elif char == 'A':
                encrypted_char = 'Z'
            else:
                encrypted_char = chr(((ord(char) - ord('A') + 1) % 26) + ord('A'))
            encrypted_message.append(encrypted_char)
        else:
            # Non-alphabetic characters are appended to the message
            encrypted_message.append(char)

    return ''.join(encrypted_message)

