def encrypt_message(ciphertext, secret_word):
    if len(secret_word) > len(ciphertext):
        raise ValueError("Secret word must be longer than the ciphertext.")

    # Pad the secret word with spaces to match the length of the ciphertext
    secret_word = " " * (len(secret_word) - len(ciphertext))

    encrypted_message = ""
    for i, char in enumerate(ciphertext):
        # Find the position of each character in the key
        key_position = ord(secret_word[i]) - ord('A')

        # Replace the character with its corresponding character from the key
        encrypted_message += chr(key_position + ord(char))

    return encrypted_message

