def autokey_cipher(ciphertext, secret_word):
    """
    Encrypts a top-secret message by swapping letters based on the key.

    :param ciphertext: A string representing the encrypted message.
    :param secret_word: A string representing the secret word to encrypt with.
    :return: The original message before encryption.
    """
    def shift_char(char, shift):
        if char.isupper():
            base = ord('A')
        elif char.islower():
            base = ord('a')
        else:
            return char
        return chr((ord(char) - base + shift) % 26 + base)

    key_length = len(secret_word)
    original_message = []

    for char in ciphertext:
        # Replace the first letter of the secret word with its corresponding character from the secret key
        if char.isupper():
            encrypted_char = chr((ord(char) - ord('A') + (key_length - 1)) % 26 + ord('A'))
        elif char.islower():
            encrypted_char = chr((ord(char) - ord('a') + (key_length - 1)) % 26 + ord('a'))
        else:
            encrypted_char = char

        original_message.append(encrypted_char)

    return ''.join(original_message)

