def has_conflict(board, row, col):
    # Check row conflicts
    for i in range(len(board)):
        if abs(row - i) == 2 and board[row][i] != 0:
            return True

    # Check column conflicts
    for i in range(len(board[0])):
        if abs(col - i) == 2 and board[i][col] != 0:
            return True

    return False

