def check_luhn_checksum(n):
    # Convert string to list of integers
    digits = [int(digit) for digit in str(n)]

    # Check if length is valid
    if len(digits) < 2 or len(digits) > 50:
        return "FAIL"

    # Initialize sum with 1 (for the first digit)
    total_sum = 1

    # Transform even-indexed digits and check checksum
    for i in range(0, len(digits), 2):
        if digits[i] * 2 > 9:
            total_sum += int(str((digits[i] * 2 - 9)))
        else:
            total_sum += digits[i]

    # Check the final sum against the expected result
    if total_sum % 10 == 0:
        return "PASS"
    else:
        return "FAIL"

