def find_winnable_board(N):
    # Validate input
    if N < 1 or N > 2000:
        print("Error: Total count must be between 1 and 2000.")
        return

    # Generate all possible distributions of counters into bins
    total_count = 1 + N
    bins = [0] * (total_count - 1)  # Start from 1 to total_count-1

    # Try all combinations of bin distribution
    for i in range(total_count):
        for j in range(i + 1, total_count):
            if bins[i] == 0:
                bins[i] = j
                break

    # Find the last bin with a counter not in the Roumba
    last_bin_index = -1
    for i in range(1, total_count):
        if bins[i] != 0 and bins[i] != N:
            last_bin_index = i
            break

    return last_bin_index, bins

