def improper_fraction(numerator: int, denominator: int) -> str:
    """
    Converts a mixed fraction (a whole number followed by a proper fraction)
    to an improper fraction.

    >>> improper_fraction(27, 12)
    '2 3/12'
    """
    # Calculate the improper fraction
    if numerator > denominator:
        return f"{numerator - denominator}/{denominator}"
    else:
        return str(numerator)

