def sort_pieces():
    # Read input: five integers separated by spaces
    numbers = [int(input()) for _ in range(5)]

    # Process the pieces:
    sorted_numbers = []
    current_piece = 0

    while current_piece < 5:
        # Find the next piece with a smaller number
        for i in range(current_piece + 1, 5):
            if numbers[current_piece] > numbers[i]:
                break
        else:
            # If no such piece is found, swap it with the first available piece
            sorted_numbers.append(numbers[current_piece])
            current_piece = (current_piece + 1) % 5

        # Add the swapped number to the result
        sorted_numbers.append(sorted_numbers[-1])  # Append the last swapped piece

    return ' '.join(map(str, sorted_numbers))

