def calculate_mosquitoes(M, P, L, E, R, S, N):
    # Initialize variables
    cur_mosquito_count = 0
    total_mosquitoes = M + P + L
    weeks_remaining = N
    adults = []

    while weeks_remaining > 0:
        # Calculate the number of eggs laid in this week
        eggs_laid = E * (1 - R)

        # Generate new species (pupa or adult) based on survival rates and update cur_mosquito_count
        for _ in range(weeks_remaining):
            if R < 0.5:
                if S > 0.25:
                    if eggs_laid <= 0:
                        break
                        adults.append(cur_mosquito_count)
                        eggs_laid = (1 - R) * 1 + R * 1  # New egg layed for the first week
                else:
                    if eggs_laid <= 0:
                        break
                    adults.append(cur_mosquito_count)
                    eggs_laid = (1 - R) * 2 + R * 1  # New egg layed for the second week
            else:
                if S > 0.5:
                    if eggs_laid <= 0:
                        break
                        adults.append(cur_mosquito_count)
                        eggs_laid = (1 - R) * 3 + R * 1  # New egg layed for the third week
                else:
                    if eggs_laid <= 0:
                        break
                    adults.append(cur_mosquito_count)
                    eggs_laid = (1 - R) * 4 + R * 1  # New egg laid for the fourth week

        # Update weeks_remaining and cur_mosquito_count
        weeks_remaining -= 1
        cur_mosquito_count += total_mosquitoes

    # Calculate the number of adults after N Sundays
    total_adults = sum(adults)

    return total_adults

