def find_biggest_smaller_number(N):
    """
    Finds the biggest integer which is smaller than N with sum of digits less by one.

    :param N: An integer (1 <= N <= 100000)
    :return: The number demanded by fox Mithra
    """

    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Start from the largest possible number and go downwards
    while True:
        if digit_sum(N) <= 1:
            return N
        else:
            N -= 1

