def is_palindrome(s):
    return s == s[::-1]

def find_min_removals(input_string):
    # Helper function to generate all permutations
    def permute(s):
        if len(s) == 1:
            return [s]
        result = []
        for i in range(len(s)):
            for rest in permute(s[:i] + s[i+1:]):
                result.append(rest + s[i])
        return result

    # Generate all permutations
    all_permutations = permute(input_string)

    # Check each permutation to see if it forms a palindrome
    valid_perms = [perm for perm in all_permutations if is_palindrome(perm)]

    # Count the number of characters that need to be removed
    total_chars = len(input_string)
    missing_chars = total_chars - sum(len(perm) for perm in valid_perms)

    return missing_chars

