def generate_square_vertices(num_iterations):
    for _ in range(num_iterations):
        side_length = 4
        num_points = side_length ** 2

        # Generate four square vertices with midpoints
        vertices = []
        for i in range(side_length):
            # Create a new vertex at the midpoint of the side
            x1 = (i * side_length) / 2 + side_length / 4
            y1 = (i * side_length) / 2 + side_length / 4
            vertices.append((x1, y1))

            # Calculate the height of a new vertex
            if i == 0:
                x_mid = (i * side_length) / 2 + side_length / 2
                y_mid = 0
            else:
                x_mid = (i * side_length) / 2 + side_length / 2
                y_mid = (i - 1) * side_length / 2
            vertices.append((x_mid, y_mid))

            # Calculate the height of a new vertex centered in the square
            for j in range(4):
                x_center = (j * side_length + i * side_length) / 2
                y_center = 0
                vertices.append((x_center, y_center))

        yield vertices

