def find_lexicographically_smallest_word(puzzle):
    # Read input lines and process each line to find the smallest word
    for row in puzzle:
        # Split the line into characters
        chars = list(row.strip())

        # Check each character if it's a letter or '#'
        for char in chars:
            if char.isalpha():
                min_word = ''

                # Iterate through the rest of the string to find the lexicographically smallest word
                for i in range(len(chars)):
                    next_char = chars[i+1]
                    if i + 1 < len(chars) and next_char != '#':
                        if not min_word or char < min_word:
                            min_word = char

                # If we found a smaller word, store it
                if min_word:
                    return min_word

    # If no valid word was found, return "No valid solution"
    return "No valid solution"

