def find_lexicographically_smallest_word(crossword):
    # Read the input from stdin
    rows, cols = map(int, input().split())

    # Ensure the size of the grid is valid
    if R < 2 or C < 2:
        raise ValueError("Grid must have at least two rows and columns.")

    # Create a set to store unique characters in each row
    char_sets = {chr(i): [] for i in range(26)}

    # Populate the sets with characters from the grid
    for i in range(rows):
        for j in range(cols):
            if crossword[i][j] != '#':
                char_sets[ord(crossword[i][j]) - ord('a')].append(crossword[i][j])

    # Find the smallest word by lexicographical order
    smallest_word = None
    for char in char_sets:
        if len(char_sets[char]) >= 2 and (smallest_word is None or char < smallest_word):
            smallest_word = char

    return smallest_word

