def can_build_closed_track(X, Y):
    if X <= 0 or Y <= 0:
        return "impossible otherwise"

    # Check if the number of level junctions exceeds the total number of tracks
    if X + Y > 1000:
        return "impossible otherwise"

    # Initialize a graph
    graph = {x: [] for x in range(1001)}

    # Populate the graph with edges
    for i in range(X):
        graph[i].append(Y - i)
        if Y - i >= 0:
            graph[Y - i].append(i)

    # Perform BFS from each level junction to find a path that includes all switches
    visited = set()
    queue = [i for i in range(1001) if i not in visited]
    while queue:
        current = queue.pop(0)

        # Check if the current point is a switch
        if current in [y for y in graph[current]]:
            return "possible"

        # Mark the current point as visited
        visited.add(current)

        # Add all adjacent points to the queue if they are not already visited
        for neighbor in graph[current]:
            if neighbor not in visited:
                queue.append(neighbor)

    # If no path includes all switches, return "impossible otherwise"
    return "impossible otherwise"

