def find_min_roads(grid):
    n = len(grid)
    dp = [float('inf')] * n

    # Base case: no roads needed to reach a single city
    for i in range(n):
        if grid[i]:
            dp[i] = 0

    # Topological sort
    from collections import deque
    q = deque()

    for i, row in enumerate(grid):
        for j in row:
            if len(row) == 1:  # Single endpoint city
                continue
            neighbors = [(i, j), (j, i)]
            for x, y in neighbors:
                if grid[x][y] not in q:
                    q.append(x)
                    dp[y] = min(dp[y], dp[i] + 1)

    return dp

