def min_macro_chars(route):
    # Check if the input is empty or contains invalid characters
    if not route or not all(char in "NSWE" for char in route):
        return 0

    # Define the macro sequence
    macros = {
        "N": [],
        "S": [],
        "E": [],
        "W": []
    }

    # Function to expand a macro sequence
    def expand_macro(sequence):
        current_sequence = sequence[:]
        for i in range(4):
            if current_sequence[i] == 'N':
                macros['S'].append(current_sequence[:i] + 'E' + current_sequence[i+1:])
            elif current_sequence[i] == 'S':
                macros['W'].append(current_sequence[:i] + 'N' + current_sequence[i+1:])
            elif current_sequence[i] == 'E':
                macros['W'].append(current_sequence[:i] + 'S' + current_sequence[i+1:])
            elif current_sequence[i] == 'W':
                macros['N'].append(current_sequence[:i] + 'E' + current_sequence[i+1:])

    # Expand the macro sequence
    for i in range(4):
        expand_macro(macros[route[i]])

    # Calculate the minimum number of characters needed
    total_chars = 0
    for sequence in macros.values():
        total_chars += len(sequence)

    return total_chars

