def calculate_total_cost(grid):
    n = len(grid)
    m = len(grid[0])

    # Initialize a list to store distances and corresponding people
    distances = [[float('inf')] * m for _ in range(n)]
    people = [set() for _ in range(n)]

    # Populate the grid with distances
    for i in range(n):
        for j in range(m):
            if grid[i][j] != 0:
                people[i].add(j)
                if i > 0:
                    distances[i-1][j] = min(distances[i-1][j], grid[i][j])
                if i < n - 1:
                    distances[i+1][j] = min(distances[i+1][j], grid[i][j])

    # Calculate total cost
    total_cost = 0
    for person in people:
        for neighbor in person:
            if neighbor not in distances[person]:
                continue
            total_cost += min(distances[person][neighbor], distances[neighbor][person]) * grid[person][neighbor]

    return total_cost

