def rotate_string(s, n):
    # Reverse the string
    reversed_s = s[::-1]

    # Perform rotation
    if 0 <= n <= 27:
        rotated_index = (n % 26)  # Rotate using modulo operation
        rotated_s = reversed_s[rotated_index:] + reversed_s[:rotated_index]
    else:
        # Special case: wrap around underscores and periods
        for char in s:
            if char.isupper():
                # Wrap around underscores
                if char == '_':
                    # Replace with the next letter
                    rotated_s = rotated_s[:-1] + 'Z'
                # Replace with the previous letter
                else:
                    # Wrap around periods
                    rotated_s = rotated_s[:-1] + 'A'
            elif char.islower():
                # Wrap around underscores and periods
                if char == '_':
                    # Replace with the next letter
                    rotated_s = rotated_s[:-1] + 'Z'
                # Replace with the previous letter
                else:
                    # Wrap around periods
                    rotated_s = rotated_s[:-1] + 'A'
    return rotated_s

