def encode_message(message):
    """
    Encodes a message using run-length encoding (RLC).

    Args:
        message (str): The input message to be encoded.

    Returns:
        str: The run-length encoded message.
    """
    # Split the message into individual characters and count occurrences of each character
    char_count = {}
    for char in message:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Create the run-length encoded string
    encoded_string = []
    current_char = None
    count = 0
    for char, count in char_count.items():
        if current_char is None or char != current_char:
            if current_char is not None:
                encoded_string.append(current_char + str(count))
            current_char = char
            count = 1
        else:
            count += 1

    # Add the last character with its run length
    if current_char is not None:
        encoded_string.append(current_char + str(count))

    return ''.join(encoded_string)

def decode_message(rle):
    """
    Decodes a run-length encoded message.

    Args:
        rle (str): The input run-length encoded message to be decoded.

    Returns:
        str: The original string corresponding to the given run-length encoding.
    """
    # Split the run-length encoded string into individual characters and count occurrences of each character
    char_count = {}
    for char in rle:
        if char != '0':
            count = int(char)
            char_count[char] = count

    # Create the original string
    decoded_string = []
    current_char = None
    run_length = 1
    for char, count in char_count.items():
        if current_char is None or char != current_char:
            if current_char is not None:
                decoded_string.append(current_char * run_length)
            current_char = char
            run_length = count

    # Add the last character with its original length
    if current_char is not None:
        decoded_string.append(current_char * run_length)

    return ''.join(decoded_string)

