def encode_message(message):
    # Edge case handling for empty input
    if not message:
        return "No content"

    # Convert message to lowercase for uniformity
    message = message.lower()

    run_length = 1
    encoded_message = []

    # Iterate over each character in the message
    for char in message:
        # If the current character is the same as the last one, increment run length
        if char == message[-1]:
            run_length += 1
        else:
            # Append the current character and its run length to the encoded message
            encoded_message.append((char, run_length))
            run_length = 1

    # Append the last character with its run length if it's not the last one in the loop
    if run_length > 0:
        encoded_message.append((message[-1], run_length))

    return ' '.join([f"{char}{run}" for char, run in encoded_message])

def decode_message(encoded_message):
    # Edge case handling for empty input
    if not encoded_message:
        return "No content"

    decoded_message = []
    current_char = None

    # Iterate over each character in the encoded message
    for item in encoded_message:
        char, run_length = item.split()

        if current_char is not None:
            # If the current character is the same as the last one, append the number of repetitions to the decoded message
            decoded_message.append((current_char, int(run_length)))
        else:
            # Append the new character and its run length to the decoded message
            decoded_message.append(char)
            current_char = char

    return ' '.join(decoded_message)

