    result = []
    current_char, count = None, 0
    for char in message:
        if current_char is not None and char == current_char:
            count += 1
        else:
            if current_char:
                result.append((current_char, count))
            current_char = char
            count = 1
    if current_char:
        result.append((current_char, count))

    # Handle the last run of characters
    if count > 0:
        result.append((current_char, count))

    return ' '.join(f'{run_length}{char}' for run_length, char in result)

def decode_message(encoded):
    """
    Decodes a run-length encoded message by repeating each character the number of times encoded by the run length.

    Args:
    encoded (str): The encoded message to be decoded.

    Returns:
    str: The original string corresponding to the given run-length encoding.
    """
    result = []
    current_char, count = None, 0
    for char in encoded:
        if current_char is not None and char == current_char:
            count += 1
        else:
            if current_char:
                # Find the original character and its run length
                i = len(result) - 1
                while result[i][1] != count:
                    i -= 1

                # Append the original character and its run length
                result.append((result[i][0], current_char))

            current_char = char
            count = 1

    if count > 0:
        result.append((current_char, count))

    return ' '.join(char for _, char in result)

