def encode_message(message):
    # Check if the input message has exactly 2 characters and starts with 'E'
    if len(message) != 2 or message[0] != 'E':
        raise ValueError("Input must start with 'E' for encoding.")

    run_length = None
    encoded_message = ""
    for char in message:
        # If we encounter a space, check if we have a complete run-length
        if char == ' ':
            if run_length is not None:
                encoded_message += str(run_length)
                run_length = 0
            continue

        # Append the current character to the encoded message
        encoded_message += char

    # Check if there's still a complete run-length after the last space
    if run_length is not None:
        encoded_message += str(run_length)

    return encoded_message

def decode_message(encoded_message):
    # Check if the input message starts with 'D' for decoding.
    if len(encoded_message) != 2 or encoded_message[0] != 'D':
        raise ValueError("Input must start with 'D' for decoding.")

    run_length = int(encoded_message[1])
    decoded_message = ""
    for i in range(0, len(encoded_message), run_length):
        char = encoded_message[i:i+run_length]
        if char == "0":
            decoded_message += "_"
        elif char.isdigit():
            decoded_message += str(int(char))
        else:
            raise ValueError("Invalid character format in decoded message.")

    return decoded_message

