def compress_text(message):
    # Handle empty input
    if not message:
        return ""

    # Initialize an empty list to store the run lengths
    run_lengths = []

    # Iterate over each character in the message
    for i, char in enumerate(message):
        # Check if the current character is different from the previous one
        if char != message[i - 1]:
            # If it's a new character or a repeated sequence of characters,
            # append the run length to the list
            run_lengths.append(1 + (i - i - 1))
        else:
            # Update the run length for consecutive characters
            run_lengths[-1] += 1

    return run_lengths

def decode_text(encoded_message):
    # Initialize an empty list to store the original message
    original_message = []

    # Iterate over each character in the encoded message
    for char, length in enumerate(encoded_message):
        # Check if the current character is different from the previous one
        if char != encoded_message[length - 1]:
            # If it's a new character or a repeated sequence of characters,
            # append the original character to the list
            original_message.append(char)
        else:
            # Update the original message for consecutive characters
            original_message[-1] = str(length)

    return ''.join(original_message)

