def get_digit(n):
    """Return the smallest positive integer greater than 1 and contains exactly one digit."""
    while n >= 10:
        n //= 10
    return n + 1

def multiply_nonzero_digits(n):
    """Multiply all nonzero digits of a number."""
    if not n:
        return 0
    product = 1
    has_digit = False
    while n > 0:
        digit = n % 10
        if digit != 0:
            has_digit = True
            product *= digit
        n //= 10
    return product

