def round_to_nearest_bill(C, K):
    # Check for edge cases
    if C == 0:
        return 0
    elif K > 9:
        raise ValueError("Cannot round bill to more than 9 times the smallest bill")

    # Calculate the integer part and multiply by 10 raised to the power of (K - (10^K - 1) / 9)
    K -= 1
    result = (10 ** K - 1) // 9 * 10 ** K

    return int(result)

