def correct_messages(S):
    # Remove trailing spaces and split the string into words
    words = S.rstrip().split()

    def remove_consecutive_chars(word):
        seen = set()
        result = []

        for char in word:
            if char not in seen:
                result.append(char)
                seen.add(char)

        return ''.join(result)

    # Process each word and remove consecutive characters
    corrected_words = [remove_consecutive_chars(w) for w in words]

    # Join the processed words back into a single string
    return ' '.join(corrected_words)

