def convert_to_base(n, base):
    """Convert a decimal number to a string in a given base."""
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        digits.append(str(n % base))
        n //= base
    return ''.join(digits[::-1])

def sum_of_squares(n, b):
    """Compute the sum of squares of the digits in base b."""
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    base_to_digits = convert_to_base(b, len(str(n)))
    squared_sums = [int(digit) ** 2 for digit in base_to_digits]

    return sum(squared_sums)

