    """
    Checks if a given grid of size n by n is correct based on the following rules:
        1. Every row has exactly as many black and white squares.
        2. Every column has exactly as many black and white squares.
        3. No row or column has more than three consecutive black squares in any direction.

    Parameters:
        - grid: A string representing the grid, where 'B' is a black square and 'W' is a white square.

    Returns:
        - An integer representing whether the grid is correct (1 if correct, 0 if incorrect).
    """
    n = len(grid)
    row_count = [0] * n
    col_count = [0] * n

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 'B':
                row_count[i] += 1
            elif grid[i][j] == 'W':
                col_count[j] += 1

    # Check rows
    for i in range(n):
        if row_count[i] > 1:
            return 0

    # Check columns
    for j in range(n):
        if col_count[j] > 1:
            return 0

    # Check diagonals (both up-right and down-left)
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 'B':
                if i != j:
                    row_count[i] += 1
                if i + j != n - 1:
                    col_count[j] += 1

    # If all checks pass, return 1; otherwise, return 0
    return 1

