    # List of buses with their drop-off points and intervals
    buses = [
        (0, [0]),  # Start at time s
        (1, [(d[0] + d[1]) // c[0], (d[-1] + d[-2]) // c[-1]]),  # End at time t
        ...  # Add more buses if needed
    ]

    # Determine the last bus's drop-off point
    if n < len(buses):
