def find_weak_vertices(graph):
    """
    Find weak vertices in an undirected graph using topological sorting.

    :param graph: A list of lists representing the adjacency matrix of the graph.
    :return: A sorted list of weak vertices.
    """
    # Initialize a dictionary to keep track of indegree
    indegree = {node: 0 for node in range(len(graph))}

    # Calculate the in-degree for each node
    for i in range(len(graph)):
        for j in range(len(graph[i])):
            if graph[i][j] == 1:
                indegree[j] += 1

    # Create a queue of nodes with an indegree of 0
    queue = [node for node, count in indegree.items() if count == 0]

    # Initialize a list to store weak vertices
    weak_vertices = []

    while queue:
        current_node = queue.pop(0)
        weak_vertices.append(current_node)

        # Decrease the indegree of all adjacent nodes
        for j in range(len(graph[current_node])):
            if graph[current_node][j] == 1 and indegree[j] > 0:
                indegree[j] -= 1
                if indegree[j] == 0:
                    queue.append(j)

    return weak_vertices

