        for word in words:
            if word not in counts:
                counts[word] = 0
            counts[word] += 1

    # Step 2: Sort the animals based on their frequency and alphabetically
    sorted_animals = sorted(counts.items(), key=lambda x: (x[1], x[0]))

    # Step 3: Collect all words that appear exactly once
    unique_animals = [animal for animal, count in sorted_animals if count == 1]

    # Step 4: Format the output
    result = []
    for i, word in enumerate(unique_animals):
        result.append(f"List {i+1}: {word} | Count: {count}")

    return result

